package com.hellodoc.service;

import com.hellodoc.dto.PrescriptionRequest;
import com.hellodoc.entity.*;
import com.hellodoc.repository.*;
import org.junit.jupiter.api.Test;
import org.springframework.web.server.ResponseStatusException;
import java.time.Instant;
import java.util.*;
import static org.junit.jupiter.api.Assertions.*;
import static org.mockito.Mockito.*;

class PrescriptionServiceTest {
 private PrescriptionRequest request(){return new PrescriptionRequest("Suivre les instructions du médecin",List.of(new PrescriptionRequest.Item("Médicament A","1 comprimé matin et soir pendant 5 jours"),new PrescriptionRequest.Item("Médicament B","Au besoin")));}
 @Test void physicianCanCreatePrescriptionOnlyForTheirCompletedVisit(){
  var appointments=mock(AppointmentRepository.class);var prescriptions=mock(PrescriptionRepository.class);var doctors=mock(DoctorProfileService.class);var users=mock(UserRepository.class);
  var physicianAccount=new UserAccount("Doc","Tor","doctor@test.invalid","hash",UserRole.DOCTOR,"ACTIVE");var doctor=mock(Doctor.class);when(doctor.getUser()).thenReturn(physicianAccount);when(doctors.own(physicianAccount.getEmail())).thenReturn(doctor);
  var appointment=new Appointment(doctor,new Patient(new UserAccount("Pat","Ient","patient@test.invalid","hash",UserRole.USER,"ACTIVE")),"Consultation","50",Instant.now().minusSeconds(7200),Instant.now().minusSeconds(3600),null);appointment.changeStatus(AppointmentStatus.COMPLETED,null);UUID appointmentId=UUID.randomUUID();
  when(appointments.findDoctorOwned(appointmentId,physicianAccount.getEmail())).thenReturn(Optional.of(appointment));when(prescriptions.save(any())).thenAnswer(i->i.getArgument(0));
  var result=new PrescriptionService(appointments,prescriptions,doctors,users).create(physicianAccount.getEmail(),appointmentId,request());
  assertEquals(2,result.items().size());assertEquals("Médicament A",result.items().get(0).medication());assertEquals("DRAFT",result.status());verify(prescriptions).save(any(Prescription.class));
 }
 @Test void physicianCanPrepareAndFinalizePrescriptionDuringConfirmedAppointment(){var appointments=mock(AppointmentRepository.class);var prescriptions=mock(PrescriptionRepository.class);var doctors=mock(DoctorProfileService.class);String email="doctor-confirmed@test.invalid";var user=new UserAccount("Doc","Tor",email,"hash",UserRole.DOCTOR,"ACTIVE");var doctor=mock(Doctor.class);when(doctor.getUser()).thenReturn(user);when(doctors.own(email)).thenReturn(doctor);var appointment=new Appointment(doctor,new Patient(new UserAccount("Pat","Ient","patient-confirmed@test.invalid","hash",UserRole.USER,"ACTIVE")),"Consultation","50",Instant.now().plusSeconds(600),Instant.now().plusSeconds(2400),null,ConsultationMode.IN_PERSON);appointment.changeStatus(AppointmentStatus.CONFIRMED,null);UUID appointmentId=UUID.randomUUID();org.springframework.test.util.ReflectionTestUtils.setField(appointment,"id",appointmentId);when(appointments.findDoctorOwned(appointmentId,email)).thenReturn(Optional.of(appointment));when(prescriptions.save(any())).thenAnswer(i->{var p=(Prescription)i.getArgument(0);org.springframework.test.util.ReflectionTestUtils.setField(p,"id",UUID.randomUUID());return p;});var service=new PrescriptionService(appointments,prescriptions,doctors,mock(UserRepository.class));var draft=service.create(email,appointmentId,request());assertEquals("DRAFT",draft.status());UUID id=draft.id();var entity=new Prescription(appointment,"Suivre les instructions",List.of(new PrescriptionItem("Médicament","Posologie")),null);org.springframework.test.util.ReflectionTestUtils.setField(entity,"id",id);when(prescriptions.findById(id)).thenReturn(Optional.of(entity));var finalized=service.finalizePrescription(email,id);assertEquals("FINALIZED",finalized.status());verify(prescriptions).flush();}
 @Test void doctorCannotPrescribeForAnotherDoctorsAppointment(){
  var appointments=mock(AppointmentRepository.class);var prescriptions=mock(PrescriptionRepository.class);var doctors=mock(DoctorProfileService.class);var email="doctor@test.invalid";UUID id=UUID.randomUUID();when(doctors.own(email)).thenReturn(mock(Doctor.class));when(appointments.findDoctorOwned(id,email)).thenReturn(Optional.empty());
  assertEquals(404,assertThrows(ResponseStatusException.class,()->new PrescriptionService(appointments,prescriptions,doctors,mock(UserRepository.class)).create(email,id,request())).getStatusCode().value());verify(prescriptions,never()).save(any());
 }
 @Test void patientPrescriptionReadUsesTheAuthenticatedPatientAndRejectsInactiveAccounts(){
  var appointments=mock(AppointmentRepository.class);var prescriptions=mock(PrescriptionRepository.class);var users=mock(UserRepository.class);var patient=new UserAccount("Pat","Ient","patient@test.invalid","hash",UserRole.USER,"ACTIVE");when(users.findByEmailIgnoreCase(patient.getEmail())).thenReturn(Optional.of(patient));when(appointments.findPatientCompletedByUserId(patient.getId())).thenReturn(List.of());
  var service=new PrescriptionService(appointments,prescriptions,mock(DoctorProfileService.class),users);assertTrue(service.forPatient(patient.getEmail()).isEmpty());verify(appointments).findPatientCompletedByUserId(patient.getId());verifyNoInteractions(prescriptions);
  when(users.findByEmailIgnoreCase("inactive@test.invalid")).thenReturn(Optional.of(new UserAccount("In","Active","inactive@test.invalid","hash",UserRole.USER,"INACTIVE")));
  assertThrows(ResponseStatusException.class,()->service.forPatient("inactive@test.invalid"));
 }
 @Test void patientSeesOnlyFinalizedPrescriptionsForCompletedAppointments(){var appointments=mock(AppointmentRepository.class);var prescriptions=mock(PrescriptionRepository.class);var users=mock(UserRepository.class);String email="patient-rx@test.invalid";var patientUser=new UserAccount("Pat","Ient",email,"hash",UserRole.USER,"ACTIVE");var doctorUser=new UserAccount("Doc","Tor","doctor-rx@test.invalid","hash",UserRole.DOCTOR,"ACTIVE");var doctor=mock(Doctor.class);when(doctor.getUser()).thenReturn(doctorUser);var appointment=new Appointment(doctor,new Patient(patientUser),"Consultation","50",Instant.now().minusSeconds(3600),Instant.now().minusSeconds(1800),null);appointment.changeStatus(AppointmentStatus.COMPLETED,null);UUID appointmentId=UUID.randomUUID();org.springframework.test.util.ReflectionTestUtils.setField(appointment,"id",appointmentId);var draft=new Prescription(appointment,"",List.of(new PrescriptionItem("Traitement","Posologie")),null);var finalized=new Prescription(appointment,"",List.of(new PrescriptionItem("Traitement partagé","Posologie")),null);finalized.finalizePrescription();when(users.findByEmailIgnoreCase(email)).thenReturn(Optional.of(patientUser));when(appointments.findPatientCompletedByUserId(patientUser.getId())).thenReturn(List.of(appointment));when(prescriptions.findByAppointmentIdInOrderByPrescribedAtDesc(List.of(appointmentId))).thenReturn(List.of(draft,finalized));var visible=new PrescriptionService(appointments,prescriptions,mock(DoctorProfileService.class),users).forPatient(email);assertEquals(1,visible.size());assertEquals("FINALIZED",visible.get(0).status());assertEquals("Traitement partagé",visible.get(0).items().get(0).medication());}
 @Test void amendmentCreatesTraceableNewVersionAndLeavesOriginalUnchanged(){
  var appointments=mock(AppointmentRepository.class);var prescriptions=mock(PrescriptionRepository.class);var doctors=mock(DoctorProfileService.class);var email="doctor@test.invalid";var account=new UserAccount("Doc","Tor",email,"hash",UserRole.DOCTOR,"ACTIVE");var doctor=mock(Doctor.class);when(doctor.getUser()).thenReturn(account);when(doctors.own(email)).thenReturn(doctor);
  var appointment=new Appointment(doctor,new Patient(new UserAccount("Pat","Ient","patient@test.invalid","hash",UserRole.USER,"ACTIVE")),"Consultation","50",Instant.now().minusSeconds(7200),Instant.now().minusSeconds(3600),null);appointment.changeStatus(AppointmentStatus.COMPLETED,null);UUID appointmentId=UUID.randomUUID(),originalId=UUID.randomUUID();org.springframework.test.util.ReflectionTestUtils.setField(appointment,"id",appointmentId);
  var original=new Prescription(appointment,"Ancienne recommandation",List.of(new PrescriptionItem("Médicament A","ancienne posologie")),null);org.springframework.test.util.ReflectionTestUtils.setField(original,"id",originalId);
  when(prescriptions.findById(originalId)).thenReturn(Optional.of(original));when(appointments.findDoctorOwned(appointmentId,email)).thenReturn(Optional.of(appointment));when(prescriptions.save(any())).thenAnswer(i->i.getArgument(0));
  var amended=new PrescriptionService(appointments,prescriptions,doctors,mock(UserRepository.class)).amend(email,originalId,request());
  assertTrue(amended.amended());assertEquals(originalId,amended.supersedesId());assertEquals("ancienne posologie",original.getItems().get(0).getInstructions());assertEquals(2,amended.items().size());
 }
}
